import SwiftUI

struct UsersView: View {
    @EnvironmentObject private var repository: APIAgentsRepository
    @State private var query = ""
    @State private var users: AdminUserPage?
    @State private var isLoading = true
    @State private var error: String?
    @State private var page = 1
    var body: some View { ScrollView { VStack(alignment: .leading, spacing: 14) {
        HStack { Text(users.map { "\($0.total) пользователей" } ?? "Пользователи").font(Typography.Font.medium(14)).foregroundStyle(EAColor.muted); Spacer() }
        HStack(spacing: 10) { Image(systemName: "magnifyingglass").foregroundStyle(EAColor.muted); TextField("Поиск по имени или email", text: $query).textInputAutocapitalization(.never).autocorrectionDisabled() }.padding(.horizontal, 14).frame(height: 48).background(.white).clipShape(RoundedRectangle(cornerRadius: 16))
        if isLoading { ForEach(0..<7, id: \.self) { _ in EASkeleton(cornerRadius: 20).frame(height: 82) } }
        else if let error { ContentUnavailableView("Не удалось загрузить пользователей", systemImage: "exclamationmark.triangle", description: Text(error)) }
        else if let users { if users.items.isEmpty { ContentUnavailableView("Ничего не найдено", systemImage: "person.crop.circle.badge.questionmark") } else { ForEach(users.items) { user in NavigationLink { UserDetailsView(userID: user.id) } label: { UserRow(user: user) }.buttonStyle(.plain) } }; pagination(users) }
    }.padding(20) }.background(EAColor.background.ignoresSafeArea()).navigationTitle("Пользователи").navigationBarTitleDisplayMode(.inline).task(id: "\(page)-\(query)") { await delayedLoad() }.refreshable { await load() } }
    private func pagination(_ data: AdminUserPage) -> some View { HStack { Button("‹ Назад") { page -= 1 }.disabled(page == 1); Spacer(); Text("\(page) / \(max(1, Int(ceil(Double(data.total) / Double(data.size)))))").font(Typography.Font.medium(13)).foregroundStyle(EAColor.muted); Spacer(); Button("Вперёд ›") { page += 1 }.disabled(page * data.size >= data.total) }.buttonStyle(.bordered).tint(EAColor.ink) }
    private func delayedLoad() async { try? await Task.sleep(for: .milliseconds(query.isEmpty ? 0 : 350)); guard !Task.isCancelled else { return }; page = query.isEmpty ? page : 1; await load() }
    private func load() async { isLoading = true; error = nil; defer { isLoading = false }; do { users = try await repository.adminUsers(page: page, limit: 20, query: query) } catch { self.error = "Проверьте соединение и права доступа." } }
}

private struct UserRow: View { let user: AdminUserListItem; var body: some View { EASurface { HStack(spacing: 12) { EAAvatar(name: user.name ?? user.email).frame(width: 46, height: 46); VStack(alignment: .leading, spacing: 4) { Text(user.name?.isEmpty == false ? user.name! : "Без имени").font(Typography.Font.semibold(16)).foregroundStyle(EAColor.ink); Text(user.email).font(Typography.Font.regular(13)).foregroundStyle(EAColor.muted).lineLimit(1) }; Spacer(); Image(systemName: "chevron.right").font(.system(size: 13, weight: .semibold)).foregroundStyle(EAColor.muted) } } } }

struct UserDetailsView: View {
    @EnvironmentObject private var repository: APIAgentsRepository
    let userID: String
    @State private var user: AdminUserDetails?
    @State private var isLoading = true
    @State private var failuresOnly = false
    @State private var error: String?
    var body: some View { ScrollView { if isLoading { VStack(spacing: 12) { ForEach(0..<5, id: \.self) { _ in EASkeleton(cornerRadius: 20).frame(height: 100) } }.padding(20) } else if let user { VStack(alignment: .leading, spacing: 16) { header(user); info(user); allergies(user); plans(user); requests(user) }.padding(20) } else { ContentUnavailableView(error ?? "Пользователь не найден", systemImage: "person.crop.circle.badge.questionmark") } }.background(EAColor.background.ignoresSafeArea()).navigationTitle("Профиль").navigationBarTitleDisplayMode(.inline).task { await load() } }
    private func header(_ u: AdminUserDetails) -> some View { HStack(spacing: 12) { EAAvatar(name: u.name ?? u.email); VStack(alignment: .leading, spacing: 4) { Text(u.name?.isEmpty == false ? u.name! : "Без имени").font(Typography.Font.bold(22)); Text(u.email).font(Typography.Font.regular(13)).foregroundStyle(EAColor.muted); Text(u.subscription ?? "free").font(Typography.Font.semibold(11)).foregroundStyle(Color(hex: "#B35F2D")) } } }
    private func info(_ u: AdminUserDetails) -> some View { UserSection("Личные данные") { LazyVGrid(columns: [GridItem(.flexible()), GridItem(.flexible())], alignment: .leading, spacing: 16) { UserField("Пол", u.gender); UserField("Телефон", u.phone); UserField("Рост", u.height.map { "\($0.formatted()) см" }); UserField("Вес", u.weight.map { "\($0.formatted()) кг" }); UserField("Активность", u.activityLevel); UserField("Дата рождения", u.birthDate?.userDate) } } }
    private func allergies(_ u: AdminUserDetails) -> some View { UserSection("Аллергии и исключения") { VStack(alignment: .leading, spacing: 10) { if u.allergies.isEmpty { Text("Аллергий нет").foregroundStyle(EAColor.muted) } else { FlowLayout(spacing: 7) { ForEach(u.allergies, id: \.self) { Text($0).font(Typography.Font.medium(12)).foregroundStyle(EAColor.danger).padding(.horizontal, 9).padding(.vertical, 6).background(EAColor.danger.opacity(0.1)).clipShape(Capsule()) } } }; if let excluded = u.excludedProducts, !excluded.isEmpty { Text(excluded).font(Typography.Font.regular(14)).foregroundStyle(EAColor.muted) } } } }
    private func plans(_ u: AdminUserDetails) -> some View { UserSection("Рационы · \(u.plans.count)") { if u.plans.isEmpty { Text("Рационов нет").foregroundStyle(EAColor.muted) } else { ForEach(u.plans) { plan in HStack { VStack(alignment: .leading) { Text(plan.createdAt.userDate).font(Typography.Font.medium(14)); Text(plan.strategy).font(Typography.Font.regular(12)).foregroundStyle(EAColor.muted) }; Spacer(); Text("\(plan.daysCount) дн.").font(Typography.Font.semibold(13)) }.padding(.vertical, 4) } } } }
    private func requests(_ u: AdminUserDetails) -> some View { let data = failuresOnly ? u.llmRequests.filter { $0.status.lowercased() == "failed" } : u.llmRequests; return UserSection("История LLM · \(u.llmRequests.count)") { VStack(alignment: .leading, spacing: 10) { Toggle("Только ошибки", isOn: $failuresOnly).tint(EAColor.ink); if data.isEmpty { Text("Запросов нет").foregroundStyle(EAColor.muted) } else { ForEach(data) { request in VStack(alignment: .leading, spacing: 4) { HStack { Text(request.requestedAt.userDate).font(Typography.Font.medium(13)); Spacer(); Text(request.status).font(Typography.Font.semibold(11)).foregroundStyle(request.status.lowercased() == "success" ? Color(hex: "#638000") : EAColor.danger) }; Text("\(String(format: "%.1f", request.durationMs / 1000)) сек · \(request.totalTokens.map(String.init) ?? "—") токенов").font(Typography.Font.regular(12)).foregroundStyle(EAColor.muted); if let error = request.errorText { Text(error).font(Typography.Font.regular(12)).foregroundStyle(EAColor.danger).lineLimit(2) } }.padding(.vertical, 5) } } } } }
    private func load() async { defer { isLoading = false }; do { user = try await repository.adminUser(id: userID) } catch { self.error = error.localizedDescription } }
}

private struct UserSection<Content: View>: View { let title: String; @ViewBuilder let content: Content; init(_ title: String, @ViewBuilder content: () -> Content) { self.title = title; self.content = content() }; var body: some View { EASurface { VStack(alignment: .leading, spacing: 14) { Text(title).font(Typography.Font.semibold(16)); content } } } }
private struct UserField: View { let label: String; let value: String?; init(_ label: String, _ value: String?) { self.label = label; self.value = value }; var body: some View { VStack(alignment: .leading, spacing: 3) { Text(label).font(Typography.Font.regular(11)).foregroundStyle(EAColor.muted); Text(value?.isEmpty == false ? value! : "—").font(Typography.Font.medium(14)).lineLimit(1) } } }
private extension String { var userDate: String { let formatter = ISO8601DateFormatter(); guard let date = formatter.date(from: self) else { return self }; return date.formatted(.dateTime.day().month(.abbreviated).year()) } }
struct FlowLayout: Layout { var spacing: CGFloat = 8; func sizeThatFits(proposal: ProposedViewSize, subviews: Subviews, cache: inout ()) -> CGSize { let width = proposal.width ?? .greatestFiniteMagnitude; var point = CGPoint.zero; var height: CGFloat = 0; for view in subviews { let size = view.sizeThatFits(.unspecified); if point.x + size.width > width { point.x = 0; point.y += height + spacing; height = 0 }; height = max(height, size.height); point.x += size.width + spacing }; return CGSize(width: width, height: point.y + height) }; func placeSubviews(in bounds: CGRect, proposal: ProposedViewSize, subviews: Subviews, cache: inout ()) { var point = bounds.origin; var rowHeight: CGFloat = 0; for view in subviews { let size = view.sizeThatFits(.unspecified); if point.x + size.width > bounds.maxX { point.x = bounds.minX; point.y += rowHeight + spacing; rowHeight = 0 }; view.place(at: point, proposal: .unspecified); rowHeight = max(rowHeight, size.height); point.x += size.width + spacing } } }
